using System;using System.IO;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro {public static class LatchInProcess {public static int Run(string folder){var j=new JavaScriptSerializer();var rows=new List<object>();IZDoc doc=null;bool pass=false;string error=null;try{var r=(Dictionary<string,object>)j.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json")));dynamic legacy=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)legacy.ZIronCADApp;string p=Path.Combine(folder,"probe.ics");File.Copy((string)r["source"],p,false);bool already;doc=app.OpenFile2(p,true,false,out already);if(already)throw new Exception("Ownership refused");var u=(IZSceneDocUtility)doc;foreach(var raw in (object[])r["ids"]){int id=Convert.ToInt32(raw);try{var part=(IZPart)u.GetElementById(id);var body=part.GetBody(true);object faceIds;var meshes=(Array)part.GetSpecifiedPolyMeshes(0.0001f,0.1f,0.02f,true,out faceIds);var mesh=(IZPolyMesh)meshes.GetValue(0);rows.Add(new{id=id,vertices=mesh.VertexCount,facets=mesh.FacetCount,vertex=mesh.GetVertex(0),facet=mesh.GetFacet(0)});}catch(Exception e){rows.Add(new{id=id,error=e.ToString()});}}pass=true;}catch(Exception e){error=e.ToString();}finally{if(doc!=null&&!doc.Modified)doc.Close();}File.WriteAllText(Path.Combine(folder,"result.json"),j.Serialize(new{passed=pass,error=error,rows=rows}));return pass?0:1;}}}
